#include <stdio.h>
#include <errno.h>
#include <unistd.h>
#include <string.h>
#include "ucl.h"

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *data = malloc(size + 1);
    if (!data) {
        fclose(f);
        return 1;
    }
    fread(data, 1, size, f);
    fclose(f);
    data[size] = '\0';

    struct ucl_parser *parser;
    parser = ucl_parser_new(0);
    ucl_parser_add_string(parser, data, size);

    if (ucl_parser_get_error(parser) != NULL) {
        printf("Parse error (expected): %s\n", ucl_parser_get_error(parser));
    }

    ucl_parser_free(parser);
    free(data);
    return 0;
}
